import{i as e,r as t,s as n,t as r}from"./app-FtcyK8lR.js";var i=JSON.parse(`{"path":"/guide/ui-config/resource.html","title":"资源管理","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1772867174000,"contributors":[{"name":"MurphyYi","username":"MurphyYi","email":"zy84338719@hotmail.com","commits":3,"url":"https://github.com/MurphyYi"}],"changelog":[{"hash":"46a94be73dccfa2afd836e97cca5b5781eccb641","time":1772867174000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"fix: 修复文档中所有内部链接使用相对路径"},{"hash":"afed90e9e326cfca3e3e296457c470d99b134c06","time":1772854292000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"docs: 为文档添加界面截图"},{"hash":"acf808fd844d46e164aa5b1e98e65abaf9fa76dd","time":1772854092000,"email":"zy84338719@hotmail.com","author":"MurphyYi","message":"docs: 添加完整的 UI配置流程和平台对接文档"}]},"filePathRelative":"guide/ui-config/resource.md"}`),a={name:`resource.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="资源管理" tabindex="-1"><a class="header-anchor" href="#资源管理">#</a> 资源管理</h1><p>资源管理功能用于上传和管理静态资源文件。本指南将帮助你高效管理项目中的各类静态资源。</p><p><img src="/rainbow_bridge/images/resources-page.png" alt="资源管理页面"></p><h2 id="概念说明" tabindex="-1"><a class="header-anchor" href="#概念说明">#</a> 概念说明</h2><h3 id="什么是资源" tabindex="-1"><a class="header-anchor" href="#什么是资源">#</a> 什么是资源？</h3><p>资源是指项目中使用的静态文件，包括但不限于：</p><table><thead><tr><th>类型</th><th>格式</th><th>使用场景</th></tr></thead><tbody><tr><td>图片</td><td>PNG, JPG, GIF, WebP, SVG</td><td>启动图、Banner、图标</td></tr><tr><td>字体</td><td>TTF, OTF, WOFF, WOFF2</td><td>自定义字体</td></tr><tr><td>文档</td><td>PDF, DOC, XLS</td><td>用户协议、帮助文档</td></tr><tr><td>音频</td><td>MP3, WAV, AAC</td><td>提示音、背景音乐</td></tr><tr><td>视频</td><td>MP4, WebM</td><td>教程视频、广告视频</td></tr><tr><td>其他</td><td>JSON, XML, ZIP</td><td>数据文件、配置包</td></tr></tbody></table><h3 id="资源与配置的关系" tabindex="-1"><a class="header-anchor" href="#资源与配置的关系">#</a> 资源与配置的关系</h3><p>资源管理是配置管理的补充，主要用于：</p><ol><li><strong>图片配置</strong>：上传图片后在配置中引用</li><li><strong>独立资源</strong>：存储不与配置关联的静态文件</li><li><strong>批量分发</strong>：通过导出功能批量分发资源</li></ol><h2 id="上传资源" tabindex="-1"><a class="header-anchor" href="#上传资源">#</a> 上传资源</h2><h3 id="通过-ui-上传" tabindex="-1"><a class="header-anchor" href="#通过-ui-上传">#</a> 通过 UI 上传</h3><ol><li>访问管理界面：<code>http://localhost:8080/rainbow-bridge</code></li><li>点击左侧导航栏的 <strong>资源管理</strong></li><li>选择环境和渠道</li><li>点击 <strong>上传资源</strong> 按钮</li><li>选择文件或拖拽上传</li><li>填写资源信息： <ul><li><strong>业务标识</strong>：用于分类管理</li><li><strong>备注</strong>：可选，描述信息</li></ul></li><li>点击 <strong>确定</strong> 上传</li></ol><h3 id="通过-api-上传" tabindex="-1"><a class="header-anchor" href="#通过-api-上传">#</a> 通过 API 上传</h3><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> <span class="token parameter variable">-X</span> POST http://localhost:8080/rainbow-bridge/api/v1/asset/upload <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;file=@banner.png&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;environment_key=prod&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;pipeline_key=main&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;business_key=marketing&quot;</span> <span class="token punctuation">\\</span></span>
<span class="line">  <span class="token parameter variable">-F</span> <span class="token string">&quot;remark=营销活动Banner&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>响应示例</strong>：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;code&quot;</span><span class="token operator">:</span> <span class="token number">0</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;message&quot;</span><span class="token operator">:</span> <span class="token string">&quot;success&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;data&quot;</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token property">&quot;file_id&quot;</span><span class="token operator">:</span> <span class="token string">&quot;uuid-xxx&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;url&quot;</span><span class="token operator">:</span> <span class="token string">&quot;/api/v1/asset/file/uuid-xxx&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token property">&quot;asset_ref&quot;</span><span class="token operator">:</span> <span class="token string">&quot;asset://uuid-xxx&quot;</span></span>
<span class="line">  <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="批量上传" tabindex="-1"><a class="header-anchor" href="#批量上传">#</a> 批量上传</h3><p>UI 支持同时选择多个文件上传：</p><ol><li>点击 <strong>上传资源</strong></li><li>选择多个文件</li><li>统一设置业务标识和备注</li><li>点击 <strong>确定</strong> 上传</li></ol><h2 id="管理资源" tabindex="-1"><a class="header-anchor" href="#管理资源">#</a> 管理资源</h2><h3 id="查看资源列表" tabindex="-1"><a class="header-anchor" href="#查看资源列表">#</a> 查看资源列表</h3><p><strong>通过 UI</strong>：</p><ol><li>进入 <strong>资源管理</strong> 页面</li><li>选择环境和渠道</li><li>查看资源列表</li></ol><p>可以按以下方式筛选：</p><ul><li>业务标识</li><li>文件类型</li><li>上传时间</li></ul><p><strong>通过 API</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> <span class="token string">&quot;http://localhost:8080/rainbow-bridge/api/v1/asset/list?environment_key=prod&amp;pipeline_key=main&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="预览资源" tabindex="-1"><a class="header-anchor" href="#预览资源">#</a> 预览资源</h3><p>对于图片、PDF等可预览的文件：</p><ol><li>在资源列表中找到目标资源</li><li>点击 <strong>预览</strong> 按钮</li><li>在弹窗中查看资源内容</li></ol><h3 id="下载资源" tabindex="-1"><a class="header-anchor" href="#下载资源">#</a> 下载资源</h3><p><strong>通过 UI</strong>：</p><ol><li>在资源列表中找到目标资源</li><li>点击 <strong>下载</strong> 按钮</li></ol><p><strong>通过 API</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="prismjs" data-ext="sh"><pre><code class="language-bash"><span class="line"><span class="token function">curl</span> <span class="token parameter variable">-O</span> http://localhost:8080/rainbow-bridge/api/v1/asset/file/uuid-xxx</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="删除资源" tabindex="-1"><a class="header-anchor" href="#删除资源">#</a> 删除资源</h3><ol><li>在资源列表中选择要删除的资源</li><li>点击 <strong>删除</strong> 按钮</li><li>确认删除操作</li></ol><div class="hint-container warning"><p class="hint-container-title">注意</p><p>删除资源后，引用该资源的配置可能无法正常工作。建议删除前检查引用关系。</p></div><h2 id="资源引用" tabindex="-1"><a class="header-anchor" href="#资源引用">#</a> 资源引用</h2><h3 id="在配置中引用" tabindex="-1"><a class="header-anchor" href="#在配置中引用">#</a> 在配置中引用</h3><p>上传资源后，可以在配置中通过 <code>asset://</code> 协议引用：</p><p><strong>图片配置</strong>：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;logo&quot;</span><span class="token operator">:</span> <span class="token string">&quot;asset://uuid-xxx&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;banner&quot;</span><span class="token operator">:</span> <span class="token string">&quot;asset://uuid-yyy&quot;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>运行时解析</strong>：</p><p>当获取运行时配置时，系统会自动解析资源引用：</p><div class="language-json line-numbers-mode" data-highlighter="prismjs" data-ext="json"><pre><code class="language-json"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">  <span class="token property">&quot;logo&quot;</span><span class="token operator">:</span> <span class="token string">&quot;https://your-domain.com/api/v1/asset/file/uuid-xxx&quot;</span><span class="token punctuation">,</span></span>
<span class="line">  <span class="token property">&quot;banner&quot;</span><span class="token operator">:</span> <span class="token string">&quot;https://your-domain.com/api/v1/asset/file/uuid-yyy&quot;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="客户端使用" tabindex="-1"><a class="header-anchor" href="#客户端使用">#</a> 客户端使用</h3><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 获取配置后直接使用</span></span>
<span class="line"><span class="token keyword">const</span> config <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">loadConfig</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 图片 URL 已解析为完整路径</span></span>
<span class="line">document<span class="token punctuation">.</span><span class="token function">getElementById</span><span class="token punctuation">(</span><span class="token string">&#39;logo&#39;</span><span class="token punctuation">)</span><span class="token punctuation">.</span>src <span class="token operator">=</span> config<span class="token punctuation">.</span>logo<span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="业务标识" tabindex="-1"><a class="header-anchor" href="#业务标识">#</a> 业务标识</h2><h3 id="什么是业务标识" tabindex="-1"><a class="header-anchor" href="#什么是业务标识">#</a> 什么是业务标识？</h3><p>业务标识（business_key）用于对资源进行分类管理，便于筛选和组织。</p><h3 id="推荐分类" tabindex="-1"><a class="header-anchor" href="#推荐分类">#</a> 推荐分类</h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">marketing     - 营销活动相关</span>
<span class="line">ui            - UI界面相关</span>
<span class="line">user          - 用户相关</span>
<span class="line">system        - 系统相关</span>
<span class="line">docs          - 文档类</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="使用场景" tabindex="-1"><a class="header-anchor" href="#使用场景">#</a> 使用场景</h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line"># 营销活动资源</span>
<span class="line">marketing/spring-sale/banner.png</span>
<span class="line">marketing/spring-sale/icon.png</span>
<span class="line"></span>
<span class="line"># UI 资源</span>
<span class="line">ui/logo.png</span>
<span class="line">ui/splash.png</span>
<span class="line"></span>
<span class="line"># 用户协议</span>
<span class="line">docs/user-agreement.pdf</span>
<span class="line">docs/privacy-policy.pdf</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="资源导出" tabindex="-1"><a class="header-anchor" href="#资源导出">#</a> 资源导出</h2><h3 id="导出单个资源" tabindex="-1"><a class="header-anchor" href="#导出单个资源">#</a> 导出单个资源</h3><p>直接通过下载按钮或 API 下载。</p><h3 id="批量导出" tabindex="-1"><a class="header-anchor" href="#批量导出">#</a> 批量导出</h3><p>使用 <a href="./export">导出配置</a> 功能，可以同时导出配置和关联的资源：</p><ol><li>进入 <strong>导出配置</strong> 页面</li><li>选择环境和渠道</li><li>勾选需要导出的配置和资源</li><li>下载 ZIP 包</li></ol><p>导出包结构：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">export.zip</span>
<span class="line">├── config.json          # 配置数据</span>
<span class="line">├── assets/              # 资源文件</span>
<span class="line">│   ├── uuid-xxx/</span>
<span class="line">│   │   └── banner.png</span>
<span class="line">│   └── uuid-yyy/</span>
<span class="line">│       └── logo.png</span>
<span class="line">└── manifest.json        # 清单文件</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="最佳实践" tabindex="-1"><a class="header-anchor" href="#最佳实践">#</a> 最佳实践</h2><h3 id="文件命名规范" tabindex="-1"><a class="header-anchor" href="#文件命名规范">#</a> 文件命名规范</h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line"># 推荐格式：模块_用途_尺寸.扩展名</span>
<span class="line">home_banner_750x400.png</span>
<span class="line">user_avatar_default.png</span>
<span class="line">app_logo_1024.png</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="文件大小优化" tabindex="-1"><a class="header-anchor" href="#文件大小优化">#</a> 文件大小优化</h3><ol><li><strong>图片压缩</strong>：上传前压缩图片，减少存储和传输成本</li><li><strong>格式选择</strong>： <ul><li>照片类使用 JPG</li><li>图标类使用 PNG 或 SVG</li><li>动画使用 GIF 或 WebP</li></ul></li><li><strong>尺寸适配</strong>：根据实际使用场景准备合适尺寸</li></ol><h3 id="资源组织建议" tabindex="-1"><a class="header-anchor" href="#资源组织建议">#</a> 资源组织建议</h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line"># 按业务模块组织</span>
<span class="line">marketing/</span>
<span class="line">  ├── banners/</span>
<span class="line">  ├── icons/</span>
<span class="line">  └── backgrounds/</span>
<span class="line"></span>
<span class="line">ui/</span>
<span class="line">  ├── logo/</span>
<span class="line">  ├── splash/</span>
<span class="line">  └── icons/</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="版本管理" tabindex="-1"><a class="header-anchor" href="#版本管理">#</a> 版本管理</h3><ol><li>更新资源时，建议上传新文件而非覆盖</li><li>在配置中更新引用</li><li>确认无误后删除旧资源</li></ol><h2 id="常见问题" tabindex="-1"><a class="header-anchor" href="#常见问题">#</a> 常见问题</h2><h3 id="q-单个文件大小有限制吗" tabindex="-1"><a class="header-anchor" href="#q-单个文件大小有限制吗">#</a> Q: 单个文件大小有限制吗？</h3><p>A: 默认限制为 50MB，可通过服务器配置调整。</p><h3 id="q-支持哪些文件格式" tabindex="-1"><a class="header-anchor" href="#q-支持哪些文件格式">#</a> Q: 支持哪些文件格式？</h3><p>A: 支持常见的图片、文档、音视频格式。如有特殊格式需求，可联系管理员。</p><h3 id="q-资源存储在哪里" tabindex="-1"><a class="header-anchor" href="#q-资源存储在哪里">#</a> Q: 资源存储在哪里？</h3><p>A: 资源存储在服务器的 <code>data/uploads/</code> 目录，或配置的对象存储服务。</p><h3 id="q-如何实现资源cdn加速" tabindex="-1"><a class="header-anchor" href="#q-如何实现资源cdn加速">#</a> Q: 如何实现资源CDN加速？</h3><p>A: 可以配置 Nginx 或 CDN 对资源路径进行加速，或使用对象存储服务。</p><h2 id="下一步" tabindex="-1"><a class="header-anchor" href="#下一步">#</a> 下一步</h2><ul><li><a href="./export">导出配置</a> - 导出配置和资源包</li><li><a href="./migration">配置迁移</a> - 迁移配置和资源到其他环境</li></ul>`,84)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};